        StringBuilder csv = new StringBuilder();
        csv.append("room,type,reservation,check_in,check_out\n");

        int occupiedCount = 0;
        for (Room room : rooms) {
            var reservations = reservationRepo.findByDateAndRoom(date, room.number());
